values (
  'en-batman-trivia',
  'Batman Trivia: How Well Do You Know the Dark Knight?',
  'Eight questions on Batman: his 1939 debut, Gotham City, the Bat-family, the Joker and the actors who wore the cowl on film.',
  'trivia',
