  '[{"id":"q1","question":"In which comic did Batman first appear?","options":[{"id":"a","text":"Action Comics #1","is_correct":false},{"id":"b","text":"Detective Comics #27","is_correct":true},{"id":"c","text":"Batman #1","is_correct":false},{"id":"d","text":"Detective Comics #1","is_correct":false}],"explanation":"Batman debuted in Detective Comics #27 in May 1939; Action Comics #1 is Superman''s debut and Batman #1 is his first solo title."},{"id":"q2","question":"What is Batman''s secret identity?","options":[{"id":"a","text":"Clark Kent","is_correct":false},{"id":"b","text":"Dick Grayson","is_correct":false},{"id":"c","text":"Bruce Wayne","is_correct":true},{"id":"d","text":"Harvey Dent","is_correct":false}],"explanation":"Bruce Wayne became Batman after watching his parents, Thomas and Martha, being murdered in Gotham."},{"id":"q3","question":"Which fictional city does Batman protect?","options":[{"id":"a","text":"Metropolis","is_correct":false},{"id":"b","text":"Central City","is_correct":false},{"id":"c","text":"Star City","is_correct":false},{"id":"d","text":"Gotham City","is_correct":true}],"explanation":"Gotham is Batman''s city; Metropolis belongs to Superman, Central City to the Flash and Star City to Green Arrow."},{"id":"q4","question":"Who is Batman''s loyal butler and father figure?","options":[{"id":"a","text":"Alfred Pennyworth","is_correct":true},{"id":"b","text":"James Gordon","is_correct":false},{"id":"c","text":"Lucius Fox","is_correct":false},{"id":"d","text":"Jason Todd","is_correct":false}],"explanation":"Alfred raised Bruce after his parents'' murder; Gordon is the police commissioner and Fox runs Wayne Enterprises."},{"id":"q5","question":"Which actor played Batman in Tim Burton''s Batman (1989)?","options":[{"id":"a","text":"Val Kilmer","is_correct":false},{"id":"b","text":"Michael Keaton","is_correct":true},{"id":"c","text":"George Clooney","is_correct":false},{"id":"d","text":"Christian Bale","is_correct":false}],"explanation":"Keaton wore the cowl in 1989 and 1992; Kilmer and Clooney followed in the 90s sequels, and Bale led the 2005 reboot."},{"id":"q6","question":"Who directed the Dark Knight trilogy (2005–2012)?","options":[{"id":"a","text":"Tim Burton","is_correct":false},{"id":"b","text":"Zack Snyder","is_correct":false},{"id":"c","text":"Matt Reeves","is_correct":false},{"id":"d","text":"Christopher Nolan","is_correct":true}],"explanation":"Nolan directed Batman Begins, The Dark Knight and The Dark Knight Rises; Reeves directed The Batman (2022)."},{"id":"q7","question":"Which villain did Heath Ledger play in The Dark Knight (2008)?","options":[{"id":"a","text":"Two-Face","is_correct":false},{"id":"b","text":"Bane","is_correct":false},{"id":"c","text":"The Joker","is_correct":true},{"id":"d","text":"Scarecrow","is_correct":false}],"explanation":"Ledger''s Joker won him a posthumous Oscar; Two-Face and Scarecrow also appear in the trilogy and Bane headlines the third film."},{"id":"q8","question":"Who was Batman''s first sidekick, the original Robin?","options":[{"id":"a","text":"Jason Todd","is_correct":false},{"id":"b","text":"Tim Drake","is_correct":false},{"id":"c","text":"Damian Wayne","is_correct":false},{"id":"d","text":"Dick Grayson","is_correct":true}],"explanation":"Dick Grayson debuted as Robin in 1940 and later became Nightwing; Todd, Drake and Wayne wore the mantle after him."}]'::jsonb,
  null,
  array['batman', 'dc comics', 'superheroes', 'trivia']::text[],
