  '[{"id":"q1","question":"¿En qué año debutó Batman en los cómics?","options":[{"id":"a","text":"1938","is_correct":false},{"id":"b","text":"1939","is_correct":true},{"id":"c","text":"1941","is_correct":false},{"id":"d","text":"1945","is_correct":false}],"explanation":"Batman apareció por primera vez en Detective Comics #27, en mayo de 1939; Superman había llegado un año antes."},{"id":"q2","question":"¿Cómo se llama la ciudad ficticia que protege Batman?","options":[{"id":"a","text":"Metrópolis","is_correct":false},{"id":"b","text":"Central City","is_correct":false},{"id":"c","text":"Gotham City","is_correct":true},{"id":"d","text":"Star City","is_correct":false}],"explanation":"Gotham es la ciudad de Batman; Metrópolis es la de Superman, Central City la de Flash y Star City la de Flecha Verde."},{"id":"q3","question":"¿Quiénes crearon a Batman?","options":[{"id":"a","text":"Stan Lee y Jack Kirby","is_correct":false},{"id":"b","text":"Bob Kane y Bill Finger","is_correct":true},{"id":"c","text":"Jerry Siegel y Joe Shuster","is_correct":false},{"id":"d","text":"William Moulton Marston","is_correct":false}],"explanation":"Kane y Finger presentaron a Batman en 1939; Siegel y Shuster crearon a Superman y Marston a Wonder Woman."},{"id":"q4","question":"¿Cómo se llama el archienemigo de Batman, el payaso del crimen?","options":[{"id":"a","text":"El Pingüino","is_correct":false},{"id":"b","text":"Dos Caras","is_correct":false},{"id":"c","text":"El Acertijo","is_correct":false},{"id":"d","text":"El Joker","is_correct":true}],"explanation":"El Joker debutó en Batman #1 (1940); el Pingüino, Dos Caras y el Acertijo también son clásicos de su galería de villanos."},{"id":"q5","question":"¿Qué actor interpretó a Batman en la trilogía de Christopher Nolan?","options":[{"id":"a","text":"Michael Keaton","is_correct":false},{"id":"b","text":"Ben Affleck","is_correct":false},{"id":"c","text":"Christian Bale","is_correct":true},{"id":"d","text":"Robert Pattinson","is_correct":false}],"explanation":"Bale protagonizó Batman Begins (2005), The Dark Knight (2008) y The Dark Knight Rises (2012)."},{"id":"q6","question":"¿Cómo se llama la identidad secreta de Catwoman?","options":[{"id":"a","text":"Selina Kyle","is_correct":true},{"id":"b","text":"Pamela Isley","is_correct":false},{"id":"c","text":"Harleen Quinzel","is_correct":false},{"id":"d","text":"Barbara Gordon","is_correct":false}],"explanation":"Selina Kyle es Catwoman; Isley es Hiedra Venenosa, Quinzel es Harley Quinn y Gordon es Batichica."},{"id":"q7","question":"¿Qué empresa dirige Bruce Wayne cuando no es Batman?","options":[{"id":"a","text":"LexCorp","is_correct":false},{"id":"b","text":"Wayne Enterprises","is_correct":true},{"id":"c","text":"Stark Industries","is_correct":false},{"id":"d","text":"Daily Planet","is_correct":false}],"explanation":"Bruce heredó Wayne Enterprises; LexCorp es de Lex Luthor y Stark Industries pertenece al universo Marvel."},{"id":"q8","question":"¿Qué asilo de Gotham encierra a la mayoría de sus villanos?","options":[{"id":"a","text":"Blackgate","is_correct":false},{"id":"b","text":"Belle Reve","is_correct":false},{"id":"c","text":"Iron Heights","is_correct":false},{"id":"d","text":"Arkham","is_correct":true}],"explanation":"Arkham es el hospital psiquiátrico de Gotham; Blackgate es la prisión común y Belle Reve la base del Escuadrón Suicida."}]'::jsonb,
