values (
  'en-superman-trivia',
  'Superman Trivia: How Well Do You Know the Man of Steel?',
  'Eight questions on Superman: his 1938 debut, Krypton, the Daily Planet, kryptonite and the actors who played the Man of Steel.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"In which comic did Superman first appear?","options":[{"id":"a","text":"Action Comics #1","is_correct":true},{"id":"b","text":"Detective Comics #27","is_correct":false},{"id":"c","text":"Superman #1","is_correct":false},{"id":"d","text":"Amazing Fantasy #15","is_correct":false}],"explanation":"Superman debuted in Action Comics #1 in June 1938; Amazing Fantasy #15 is Spider-Man''s debut, a Marvel comic."},{"id":"q2","question":"What is Superman''s home planet?","options":[{"id":"a","text":"Oa","is_correct":false},{"id":"b","text":"Krypton","is_correct":true},{"id":"c","text":"Apokolips","is_correct":false},{"id":"d","text":"Tamaran","is_correct":false}],"explanation":"Kal-El was sent to Earth from Krypton before it exploded; Oa hosts the Green Lantern Corps and Apokolips is Darkseid''s world."},{"id":"q3","question":"Where does Clark Kent work as a reporter?","options":[{"id":"a","text":"The Daily Bugle","is_correct":false},{"id":"b","text":"The Gotham Gazette","is_correct":false},{"id":"c","text":"The Daily Planet","is_correct":true},{"id":"d","text":"The Central City Picture News","is_correct":false}],"explanation":"Clark works at Metropolis'' Daily Planet; the Daily Bugle is J. Jonah Jameson''s paper in the Spider-Man universe."},{"id":"q4","question":"Which substance weakens Superman?","options":[{"id":"a","text":"Vibranium","is_correct":false},{"id":"b","text":"Adamantium","is_correct":false},{"id":"c","text":"Nth metal","is_correct":false},{"id":"d","text":"Kryptonite","is_correct":true}],"explanation":"Kryptonite are radioactive fragments of his destroyed home planet; vibranium and adamantium belong to Marvel."},{"id":"q5","question":"Which actor played Superman in the 1978 film and its sequels?","options":[{"id":"a","text":"Christopher Reeve","is_correct":true},{"id":"b","text":"Henry Cavill","is_correct":false},{"id":"c","text":"Brandon Routh","is_correct":false},{"id":"d","text":"George Reeves","is_correct":false}],"explanation":"Reeve starred from 1978 to 1987; George Reeves played him on 1950s TV, Routh in Superman Returns and Cavill in Man of Steel."},{"id":"q6","question":"In which town did Clark Kent grow up on Earth?","options":[{"id":"a","text":"Gotham","is_correct":false},{"id":"b","text":"Metropolis","is_correct":false},{"id":"c","text":"Smallville","is_correct":true},{"id":"d","text":"Coast City","is_correct":false}],"explanation":"The Kents found baby Kal-El near Smallville, Kansas; Coast City is Hal Jordan''s hometown."},{"id":"q7","question":"Who created Superman?","options":[{"id":"a","text":"Bob Kane and Bill Finger","is_correct":false},{"id":"b","text":"Stan Lee and Jack Kirby","is_correct":false},{"id":"c","text":"William Moulton Marston","is_correct":false},{"id":"d","text":"Jerry Siegel and Joe Shuster","is_correct":true}],"explanation":"Siegel and Shuster created Superman as teenagers in Cleveland; Kane and Finger created Batman and Marston created Wonder Woman."},{"id":"q8","question":"Who is Superman''s archenemy, the brilliant billionaire of Metropolis?","options":[{"id":"a","text":"Lex Luthor","is_correct":true},{"id":"b","text":"Brainiac","is_correct":false},{"id":"c","text":"Doomsday","is_correct":false},{"id":"d","text":"General Zod","is_correct":false}],"explanation":"Lex Luthor has been Superman''s nemesis since 1940; Brainiac, Doomsday and Zod are also major foes but not his archenemy."}]'::jsonb,
  null,
