insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-wonder-woman-trivia',
  'Wonder Woman Trivia: How Well Do You Know the Amazon?',
  'Eight questions on Wonder Woman: Themyscira, the Lasso of Truth, her 1941 debut and the films of the DC universe.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"What is the name of the island home where the Amazons raised Diana?","options":[{"id":"a","text":"Themyscira","is_correct":true},{"id":"b","text":"Olympus","is_correct":false},{"id":"c","text":"Atlantis","is_correct":false},{"id":"d","text":"Krypton","is_correct":false}],"explanation":"Themyscira is the hidden island of the Amazons; Atlantis belongs to Aquaman and Krypton is Superman''s lost world."},{"id":"q2","question":"What is Wonder Woman''s civilian identity?","options":[{"id":"a","text":"Barbara Gordon","is_correct":false},{"id":"b","text":"Diana Prince","is_correct":true},{"id":"c","text":"Selina Kyle","is_correct":false},{"id":"d","text":"Dinah Lance","is_correct":false}],"explanation":"Diana Prince is her name in the human world; Gordon is Batgirl, Kyle is Catwoman and Lance is Black Canary."},{"id":"q3","question":"Which of Wonder Woman''s artifacts forces anyone it holds to tell the truth?","options":[{"id":"a","text":"The Bracelets of Submission","is_correct":false},{"id":"b","text":"The Invisible Jet","is_correct":false},{"id":"c","text":"The Lasso of Truth","is_correct":true},{"id":"d","text":"The God Killer sword","is_correct":false}],"explanation":"The Lasso of Truth compels honesty; her bracelets deflect bullets and the jet is just her transport."},{"id":"q4","question":"Who created Wonder Woman in 1941?","options":[{"id":"a","text":"Bob Kane","is_correct":false},{"id":"b","text":"Jerry Siegel","is_correct":false},{"id":"c","text":"Stan Lee","is_correct":false},{"id":"d","text":"William Moulton Marston","is_correct":true}],"explanation":"Marston, a psychologist, created her and also developed an early lie-detector prototype — the seed of the Lasso of Truth."},{"id":"q5","question":"Who played Wonder Woman in the 2017 film?","options":[{"id":"a","text":"Lynda Carter","is_correct":false},{"id":"b","text":"Gal Gadot","is_correct":true},{"id":"c","text":"Connie Nielsen","is_correct":false},{"id":"d","text":"Adrianne Palicki","is_correct":false}],"explanation":"Gadot starred in Wonder Woman (2017); Carter played her on 1970s TV and Nielsen plays her mother, Queen Hippolyta."},{"id":"q6","question":"Who is Wonder Woman''s mother?","options":[{"id":"a","text":"Hera","is_correct":false},{"id":"b","text":"Antiope","is_correct":false},{"id":"c","text":"Queen Hippolyta","is_correct":true},{"id":"d","text":"Athena","is_correct":false}],"explanation":"Hippolyta is the queen of the Amazons and Diana''s mother; Antiope is her aunt and the gods are Olympian figures."},{"id":"q7","question":"In which comic did Wonder Woman debut in 1941?","options":[{"id":"a","text":"All Star Comics #8","is_correct":true},{"id":"b","text":"Sensation Comics #1","is_correct":false},{"id":"c","text":"Wonder Woman #1","is_correct":false},{"id":"d","text":"Detective Comics #27","is_correct":false}],"explanation":"She first appeared in All Star Comics #8 (1941) and took the cover of Sensation Comics #1 a month later."},{"id":"q8","question":"What can Wonder Woman do with her bracelets?","options":[{"id":"a","text":"Shoot lasers","is_correct":false},{"id":"b","text":"Deflect bullets","is_correct":true},{"id":"c","text":"Become invisible","is_correct":false},{"id":"d","text":"Freeze time","is_correct":false}],"explanation":"Her Bracelets of Submission deflect bullets and energy blasts — a signature move in comics and films alike."}]'::jsonb,
  null,
  array['wonder woman', 'dc comics', 'superheroes', 'trivia']::text[],
