values (
  'es-trivia-wonder-woman',
  'Trivia de Wonder Woman: ¿cuánto sabes de la amazona?',
  'Ocho preguntas sobre Wonder Woman: Temiscira, el Lazo de la Verdad, su debut de 1941 y las películas de Gal Gadot.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"¿Cómo se llama la isla de las amazonas donde creció Diana?","options":[{"id":"a","text":"Olimpo","is_correct":false},{"id":"b","text":"Temiscira","is_correct":true},{"id":"c","text":"Atlántida","is_correct":false},{"id":"d","text":"Krypton","is_correct":false}],"explanation":"Temiscira es la isla oculta de las amazonas; la Atlántida es el reino de Aquaman y Krypton el mundo perdido de Superman."},{"id":"q2","question":"¿Cuál es el nombre civil de Wonder Woman?","options":[{"id":"a","text":"Diana Prince","is_correct":true},{"id":"b","text":"Barbara Gordon","is_correct":false},{"id":"c","text":"Selina Kyle","is_correct":false},{"id":"d","text":"Kara Zor-El","is_correct":false}],"explanation":"Diana Prince es su nombre en el mundo humano; Gordon es Batichica, Kyle es Catwoman y Zor-El es Supergirl."},{"id":"q3","question":"¿Qué objeto de Wonder Woman obliga a decir la verdad a quien atrapa?","options":[{"id":"a","text":"Los brazaletes","is_correct":false},{"id":"b","text":"El jet invisible","is_correct":false},{"id":"c","text":"La espada God Killer","is_correct":false},{"id":"d","text":"El Lazo de la Verdad","is_correct":true}],"explanation":"El Lazo de la Verdad obliga a confesar; los brazaletes desvían balas y el jet es solo su transporte."},{"id":"q4","question":"¿Qué actriz interpretó a Wonder Woman en la película de 2017?","options":[{"id":"a","text":"Lynda Carter","is_correct":false},{"id":"b","text":"Connie Nielsen","is_correct":false},{"id":"c","text":"Gal Gadot","is_correct":true},{"id":"d","text":"Morena Baccarin","is_correct":false}],"explanation":"Gadot protagonizó Wonder Woman (2017); Carter la interpretó en la televisión de los años 70."},{"id":"q5","question":"¿Quién es la madre de Diana?","options":[{"id":"a","text":"La reina Hipólita","is_correct":true},{"id":"b","text":"Hera","is_correct":false},{"id":"c","text":"Antíope","is_correct":false},{"id":"d","text":"Artemisa","is_correct":false}],"explanation":"Hipólita es la reina de las amazonas y madre de Diana; Antíope es su tía y las demás figuran en el panteón."},{"id":"q6","question":"¿Qué grupo de guerreras crió a Diana?","options":[{"id":"a","text":"Las valquirias","is_correct":false},{"id":"b","text":"Las furias","is_correct":false},{"id":"c","text":"Las amazonas","is_correct":true},{"id":"d","text":"Las sirenas","is_correct":false}],"explanation":"Diana creció entre las amazonas de Temiscira; las valquirias pertenecen a la mitología nórdica."},{"id":"q7","question":"¿En qué década debutó Wonder Woman en los cómics?","options":[{"id":"a","text":"Los años 30","is_correct":false},{"id":"b","text":"Los años 40","is_correct":true},{"id":"c","text":"Los años 50","is_correct":false},{"id":"d","text":"Los años 60","is_correct":false}],"explanation":"Debutó en All Star Comics #8, en 1941; Superman llegó en 1938 y Batman en 1939."},{"id":"q8","question":"¿Cómo se llama la villana felina que es archienemiga de Wonder Woman?","options":[{"id":"a","text":"Catwoman","is_correct":false},{"id":"b","text":"Circe","is_correct":false},{"id":"c","text":"Giganta","is_correct":false},{"id":"d","text":"Cheetah","is_correct":true}],"explanation":"Cheetah (Barbara Ann Minerva) es su némesis felina; Catwoman es de Gotham, aunque Circe y Giganta también enemigan a Diana."}]'::jsonb,
  null,
  array['wonder woman', 'dc comics', 'superhéroes', 'trivia']::text[],
