  '[{"id":"q1","question":"What is Barry Allen''s day job when he is not the Flash?","options":[{"id":"a","text":"Forensic scientist","is_correct":true},{"id":"b","text":"Newspaper reporter","is_correct":false},{"id":"c","text":"Police detective","is_correct":false},{"id":"d","text":"Firefighter","is_correct":false}],"explanation":"Barry works in the Central City police crime lab; a bolt of lightning and spilled chemicals gave him his speed."},{"id":"q2","question":"Which energy field gives the Flash his speed?","options":[{"id":"a","text":"The Power Cosmic","is_correct":false},{"id":"b","text":"The Speed Force","is_correct":true},{"id":"c","text":"The Force","is_correct":false},{"id":"d","text":"Gamma radiation","is_correct":false}],"explanation":"The Speed Force powers every Flash; the Power Cosmic belongs to Marvel and gamma radiation created the Hulk."},{"id":"q3","question":"Who was the first Flash of the Golden Age comics?","options":[{"id":"a","text":"Barry Allen","is_correct":false},{"id":"b","text":"Wally West","is_correct":false},{"id":"c","text":"Jay Garrick","is_correct":true},{"id":"d","text":"Bart Allen","is_correct":false}],"explanation":"Jay Garrick debuted in Flash Comics #1 (1940); Barry Allen arrived in 1956 and opened the multiverse era."},{"id":"q4","question":"Which city does the Flash protect?","options":[{"id":"a","text":"Gotham City","is_correct":false},{"id":"b","text":"Metropolis","is_correct":false},{"id":"c","text":"Coast City","is_correct":false},{"id":"d","text":"Central City","is_correct":true}],"explanation":"The Flash runs Central City; Coast City is Green Lantern''s home and the other two need no introduction."},{"id":"q5","question":"What is the name of the time-traveling speedster obsessed with destroying Barry Allen''s life?","options":[{"id":"a","text":"Captain Cold","is_correct":false},{"id":"b","text":"Eobard Thawne","is_correct":true},{"id":"c","text":"Gorilla Grodd","is_correct":false},{"id":"d","text":"Mirror Master","is_correct":false}],"explanation":"Eobard Thawne, the Reverse-Flash, came from the future to torment Barry; Cold, Grodd and Mirror Master are his Rogues."},{"id":"q6","question":"What is the civilian name of the original Kid Flash?","options":[{"id":"a","text":"Wally West","is_correct":true},{"id":"b","text":"Bart Allen","is_correct":false},{"id":"c","text":"Jesse Quick","is_correct":false},{"id":"d","text":"Jay Garrick","is_correct":false}],"explanation":"Wally West, Iris''s nephew, was the original Kid Flash and later took over as the Flash himself."},{"id":"q7","question":"In which 1956 comic did Barry Allen first appear, kicking off the Silver Age?","options":[{"id":"a","text":"Flash Comics #1","is_correct":false},{"id":"b","text":"The Flash #1","is_correct":false},{"id":"c","text":"Showcase #4","is_correct":true},{"id":"d","text":"All-Flash #1","is_correct":false}],"explanation":"Showcase #4 introduced Barry and is considered the start of the Silver Age; Flash Comics #1 belongs to Jay Garrick."},{"id":"q8","question":"Which actor played Barry Allen in the Justice League films?","options":[{"id":"a","text":"Grant Gustin","is_correct":false},{"id":"b","text":"John Wesley Shipp","is_correct":false},{"id":"c","text":"Ezra Miller","is_correct":true},{"id":"d","text":"Tom Cavanagh","is_correct":false}],"explanation":"Miller played him on the big screen; Gustin starred in the long-running TV series and Shipp in the 1990 show."}]'::jsonb,
  null,
