values (
  'es-trivia-flash',
  'Trivia de Flash: ¿cuánto sabes del multiverso DC?',
  'Ocho preguntas sobre Flash: Barry Allen, la Fuerza de la Velocidad, Central City, el multiverso y sus villanos veloces.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"¿Cómo se llama la identidad civil del Flash de la Edad de Plata?","options":[{"id":"a","text":"Wally West","is_correct":false},{"id":"b","text":"Barry Allen","is_correct":true},{"id":"c","text":"Jay Garrick","is_correct":false},{"id":"d","text":"Hal Jordan","is_correct":false}],"explanation":"Barry Allen es el Flash de la Edad de Plata; Garrick fue el primero y Wally su sucesor."},{"id":"q2","question":"¿De qué fuente de energía obtiene Flash su velocidad?","options":[{"id":"a","text":"La Fuerza de la Velocidad","is_correct":true},{"id":"b","text":"El Poder Cósmico","is_correct":false},{"id":"c","text":"La radiación gamma","is_correct":false},{"id":"d","text":"El anillo de poder","is_correct":false}],"explanation":"La Speed Force alimenta a todos los velocistas; la radiación gamma creó a Hulk y el anillo es de los Green Lanterns."},{"id":"q3","question":"¿En qué ciudad ficticia patrulla Flash?","options":[{"id":"a","text":"Gotham City","is_correct":false},{"id":"b","text":"Metrópolis","is_correct":false},{"id":"c","text":"Star City","is_correct":false},{"id":"d","text":"Central City","is_correct":true}],"explanation":"Flash corre por Central City; Gotham es de Batman, Metrópolis de Superman y Star City de Flecha Verde."},{"id":"q4","question":"¿Quién fue el primer Flash de los cómics?","options":[{"id":"a","text":"Jay Garrick","is_correct":true},{"id":"b","text":"Barry Allen","is_correct":false},{"id":"c","text":"Wally West","is_correct":false},{"id":"d","text":"Bart Allen","is_correct":false}],"explanation":"Jay Garrick debutó en Flash Comics #1 (1940); Barry Allen llegó en 1956."},{"id":"q5","question":"¿Qué actor interpretó a Flash en la serie de televisión (2014–2023)?","options":[{"id":"a","text":"Ezra Miller","is_correct":false},{"id":"b","text":"Tom Cavanagh","is_correct":false},{"id":"c","text":"Grant Gustin","is_correct":true},{"id":"d","text":"John Wesley Shipp","is_correct":false}],"explanation":"Gustin fue Barry Allen durante nueve temporadas; Miller lo interpretó en el cine y Shipp en la serie de 1990."},{"id":"q6","question":"¿Cómo se llama el enemigo de Flash que domina el frío?","options":[{"id":"a","text":"Mirror Master","is_correct":false},{"id":"b","text":"Gorilla Grodd","is_correct":false},{"id":"c","text":"El Trickster","is_correct":false},{"id":"d","text":"Capitán Frío","is_correct":true}],"explanation":"Leonard Snart, el Capitán Frío, lidera los Rogues con su pistola de hielo; Grodd es el gorila psíquico de Gorilla City."},{"id":"q7","question":"¿Cómo se llama el sobrino de Iris West que se convirtió en Kid Flash?","options":[{"id":"a","text":"Wally West","is_correct":true},{"id":"b","text":"Bart Allen","is_correct":false},{"id":"c","text":"Barry Allen","is_correct":false},{"id":"d","text":"Joe West","is_correct":false}],"explanation":"Wally West fue el primer Kid Flash y después heredó el manto de Flash; Joe West es el padre de Iris."},{"id":"q8","question":"¿Qué evento de 2011 reinició el universo DC después de que Barry viajara al pasado?","options":[{"id":"a","text":"Crisis on Infinite Earths","is_correct":false},{"id":"b","text":"Flashpoint","is_correct":true},{"id":"c","text":"Infinite Crisis","is_correct":false},{"id":"d","text":"Final Crisis","is_correct":false}],"explanation":"En Flashpoint Barry salva a su madre y altera la línea temporal, lo que dio origen a The New 52."}]'::jsonb,
  null,
  array['flash', 'dc comics', 'superhéroes', 'trivia']::text[],
