   is_featured, is_ai_generated, published_at)
values (
  'en-justice-league-trivia',
  'Justice League Trivia: How Well Do You Know DC''s Heroes?',
  'Eight questions on the Justice League: its 1960 debut, founding heroes, the Watchtower and villains like Darkseid.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"In which comic did the Justice League first appear?","options":[{"id":"a","text":"Justice League of America #1","is_correct":false},{"id":"b","text":"The Brave and the Bold #28","is_correct":true},{"id":"c","text":"Action Comics #1","is_correct":false},{"id":"d","text":"All Star Comics #3","is_correct":false}],"explanation":"The League debuted in The Brave and the Bold #28 (1960); All Star Comics #3 introduced the earlier Justice Society."},{"id":"q2","question":"What is the name of the Justice League''s orbital headquarters?","options":[{"id":"a","text":"The Hall of Justice","is_correct":false},{"id":"b","text":"The Fortress of Solitude","is_correct":false},{"id":"c","text":"The Watchtower","is_correct":true},{"id":"d","text":"The Batcave","is_correct":false}],"explanation":"The Watchtower orbits Earth; the Hall of Justice is their ground HQ, the Fortress is Superman''s and the Batcave is Batman''s."},{"id":"q3","question":"Which of these heroes was NOT a founding member of the Justice League?","options":[{"id":"a","text":"Aquaman","is_correct":false},{"id":"b","text":"Martian Manhunter","is_correct":false},{"id":"c","text":"The Flash","is_correct":false},{"id":"d","text":"Green Arrow","is_correct":true}],"explanation":"The founders were Superman, Batman, Wonder Woman, Flash, Green Lantern, Aquaman and Martian Manhunter; Green Arrow joined later."},{"id":"q4","question":"Which planet does Darkseid rule?","options":[{"id":"a","text":"Apokolips","is_correct":true},{"id":"b","text":"Krypton","is_correct":false},{"id":"c","text":"Oa","is_correct":false},{"id":"d","text":"New Genesis","is_correct":false}],"explanation":"Darkseid rules Apokolips, the hellish twin of New Genesis; Oa is the Green Lantern Corps'' base."},{"id":"q5","question":"What is Aquaman''s real name?","options":[{"id":"a","text":"Orm Marius","is_correct":false},{"id":"b","text":"Arthur Curry","is_correct":true},{"id":"c","text":"Nuidis Vulko","is_correct":false},{"id":"d","text":"Tom Curry","is_correct":false}],"explanation":"Arthur Curry is the king of Atlantis; Orm is his half-brother Ocean Master, Vulko his adviser and Tom his father."},{"id":"q6","question":"What is Cyborg''s real name?","options":[{"id":"a","text":"Victor Stone","is_correct":true},{"id":"b","text":"Silas Stone","is_correct":false},{"id":"c","text":"Vic Sage","is_correct":false},{"id":"d","text":"John Henry Irons","is_correct":false}],"explanation":"Victor Stone became Cyborg after his father Silas rebuilt him; Vic Sage is The Question and Irons is Steel."},{"id":"q7","question":"What is Martian Manhunter''s real name?","options":[{"id":"a","text":"M''gann M''orzz","is_correct":false},{"id":"b","text":"Kal-El","is_correct":false},{"id":"c","text":"Koriand''r","is_correct":false},{"id":"d","text":"J''onn J''onzz","is_correct":true}],"explanation":"J''onn J''onzz is the last green Martian and a League founder; M''gann is Miss Martian and Koriand''r is Starfire."},{"id":"q8","question":"Which team gathers the League''s worst enemies, usually led by Lex Luthor?","options":[{"id":"a","text":"The Suicide Squad","is_correct":false},{"id":"b","text":"The Legion of Doom","is_correct":true},{"id":"c","text":"The Teen Titans","is_correct":false},{"id":"d","text":"The Court of Owls","is_correct":false}],"explanation":"The Legion of Doom unites arch-villains against the League; the Titans are young heroes and the Court haunts Gotham."}]'::jsonb,
  null,
  array['justice league', 'dc comics', 'superheroes', 'trivia']::text[],
  3,
  'published',
