values (
  'es-trivia-liga-de-la-justicia',
  'Trivia de la Liga de la Justicia: ¿cuánto sabes de DC?',
  'Ocho preguntas sobre la Liga de la Justicia: su debut de 1960, los héroes fundadores, la Atalaya y villanos como Darkseid.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"¿Cuál de estos héroes NO fue miembro fundador de la Liga de la Justicia?","options":[{"id":"a","text":"Batman","is_correct":false},{"id":"b","text":"Flecha Verde","is_correct":true},{"id":"c","text":"Wonder Woman","is_correct":false},{"id":"d","text":"Aquaman","is_correct":false}],"explanation":"Los fundadores fueron Superman, Batman, Wonder Woman, Flash, Green Lantern, Aquaman y el Detective Marciano; Flecha Verde se unió después."},{"id":"q2","question":"¿Cómo se llama la base orbital de la Liga?","options":[{"id":"a","text":"El Salón de la Justicia","is_correct":false},{"id":"b","text":"La Atalaya","is_correct":true},{"id":"c","text":"La Fortaleza de la Soledad","is_correct":false},{"id":"d","text":"La Baticueva","is_correct":false}],"explanation":"La Atalaya orbita la Tierra; el Salón de la Justicia es la base terrestre y las otras dos pertenecen a Superman y Batman."},{"id":"q3","question":"¿Qué villano gobierna el planeta Apokolips?","options":[{"id":"a","text":"Brainiac","is_correct":false},{"id":"b","text":"Lex Luthor","is_correct":false},{"id":"c","text":"Darkseid","is_correct":true},{"id":"d","text":"Doomsday","is_correct":false}],"explanation":"Darkseid es el tirano de Apokolips y la mayor amenaza cósmica de la Liga; Doomsday mató a Superman en 1992."},{"id":"q4","question":"¿Cómo se llama el reino submarino que gobierna Aquaman?","options":[{"id":"a","text":"Temiscira","is_correct":false},{"id":"b","text":"Kandor","is_correct":false},{"id":"c","text":"Gorilla City","is_correct":false},{"id":"d","text":"La Atlántida","is_correct":true}],"explanation":"Aquaman reina en la Atlántida; Temiscira es de las amazonas y Kandor es la ciudad kryptoniana embotellada."},{"id":"q5","question":"¿Quién lidera habitualmente a la Legión del Mal contra la Liga?","options":[{"id":"a","text":"Lex Luthor","is_correct":true},{"id":"b","text":"El Joker","is_correct":false},{"id":"c","text":"Sinestro","is_correct":false},{"id":"d","text":"Brainiac","is_correct":false}],"explanation":"Lex Luthor, el archienemigo de Superman, suele encabezar la Legión del Mal; el Joker y Sinestro son villanos de Batman y Green Lantern."},{"id":"q6","question":"¿De qué planeta proviene el Detective Marciano?","options":[{"id":"a","text":"Venus","is_correct":false},{"id":"b","text":"Krypton","is_correct":false},{"id":"c","text":"Marte","is_correct":true},{"id":"d","text":"Thanagar","is_correct":false}],"explanation":"J''onn J''onzz es el último marciano verde; Thanagar es el mundo de Hawkman y Hawkgirl."},{"id":"q7","question":"¿Qué película de 2017 reunió a la Liga de la Justicia en el cine?","options":[{"id":"a","text":"Batman v Superman","is_correct":false},{"id":"b","text":"Man of Steel","is_correct":false},{"id":"c","text":"Suicide Squad","is_correct":false},{"id":"d","text":"Justice League","is_correct":true}],"explanation":"Justice League (2017) juntó al equipo en la pantalla grande; Batman v Superman y Suicide Squad salieron un año antes."},{"id":"q8","question":"¿Cuál es el nombre real del Green Lantern fundador de la Liga?","options":[{"id":"a","text":"Hal Jordan","is_correct":true},{"id":"b","text":"John Stewart","is_correct":false},{"id":"c","text":"Guy Gardner","is_correct":false},{"id":"d","text":"Kyle Rayner","is_correct":false}],"explanation":"Hal Jordan fue el Green Lantern fundador de 1960; Stewart, Gardner y Rayner llevaron el anillo después."}]'::jsonb,
  null,
  array['liga de la justicia', 'dc comics', 'superhéroes', 'trivia']::text[],
